-- Base de datos: nopy_nogain
CREATE DATABASE IF NOT EXISTS nopy_nogain;
USE nopy_nogain;

-- 1. Tabla de Usuarios:
CREATE TABLE IF NOT EXISTS usuarios (
    dni VARCHAR(20) PRIMARY KEY,
    nombre VARCHAR(255),
    apellido VARCHAR(255),
    peso FLOAT,
    altura FLOAT,
    sexo VARCHAR(20)
);

-- 2. Tabla de Ejercicios:
CREATE TABLE IF NOT EXISTS ejercicios (
    id_ejercicio INT AUTO_INCREMENT PRIMARY KEY,
    dni_usuario VARCHAR(20) DEFAULT NULL,
    nombre VARCHAR(255),
    grupo_muscular VARCHAR(255),
    tipo_ejercicio VARCHAR(50),
    activo BOOLEAN DEFAULT TRUE,
    FOREIGN KEY (dni_usuario) REFERENCES usuarios(dni) ON DELETE CASCADE
);

-- 3. Tabla de Rutinas:
CREATE TABLE IF NOT EXISTS rutinas (
    id_rutina INT AUTO_INCREMENT PRIMARY KEY,
    dni_usuario VARCHAR(20),
    nombre_rutina VARCHAR(255),
    cantidad_dias INT,
    FOREIGN KEY (dni_usuario) REFERENCES usuarios(dni) ON DELETE CASCADE
);

-- 4. Tabla de Días de Rutina:
CREATE TABLE IF NOT EXISTS rutina_dias (
    id_rutina_dia INT AUTO_INCREMENT PRIMARY KEY,
    id_rutina INT,
    numero_dia INT,
    grupo_muscular VARCHAR(255),
    FOREIGN KEY (id_rutina) REFERENCES rutinas(id_rutina) ON DELETE CASCADE
);

-- 5. Tabla de Ejercicios asignados por Día:
CREATE TABLE IF NOT EXISTS rutina_ejercicios (
    id_rutina_ejercicio INT AUTO_INCREMENT PRIMARY KEY,
    id_rutina_dia INT,
    id_ejercicio INT,
    cantidad_series INT,
    FOREIGN KEY (id_rutina_dia) REFERENCES rutina_dias(id_rutina_dia) ON DELETE CASCADE,
    FOREIGN KEY (id_ejercicio) REFERENCES ejercicios(id_ejercicio) ON DELETE CASCADE
);

-- 6. Tabla de Registros de Entrenamiento:
CREATE TABLE IF NOT EXISTS registros_entrenamiento (
    id_registro INT AUTO_INCREMENT PRIMARY KEY,
    dni_usuario VARCHAR(20),
    id_ejercicio INT,
    id_rutina INT DEFAULT NULL,
    numero_dia INT DEFAULT NULL,
    fecha DATE,
    serie_numero INT,
    peso_kg FLOAT,
    repeticiones INT,
    UNIQUE KEY serie_unica (dni_usuario, id_ejercicio, fecha, serie_numero),
    FOREIGN KEY (dni_usuario) REFERENCES usuarios(dni) ON DELETE CASCADE,
    FOREIGN KEY (id_ejercicio) REFERENCES ejercicios(id_ejercicio) ON DELETE CASCADE,
    FOREIGN KEY (id_rutina) REFERENCES rutinas(id_rutina) ON DELETE SET NULL
);

